def compute(vars):
    high_prices = [vars["v1"], vars["v2"], vars["v3"], vars["v4"]]
    threshold = 85.00
    qualifying_quarters = [price for price in high_prices if price > threshold]
    result = len(qualifying_quarters)

    return {
        "value": result,
        "trace": {
            "high_prices": high_prices,
            "threshold": threshold,
            "qualifying_quarters": qualifying_quarters,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "count"
            }
        }
    }
